        uint thisBefore = address(this).balance;

        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint potAfter = c.pot();
        uint thisAfter = address(this).balance;

        // General rule: exact ticket amount never reverts, and pot either resets to 0
        // (caller wins pot minus fee) or grows by amount (caller loses the ticket).
        assert(!reverted && (
            (potAfter == 0 && thisAfter == thisBefore + potBefore + amount - 1)
            ||
            (potAfter == potBefore + amount && thisAfter == thisBefore - amount)
        ));
    }

    receive() external payable {}
}

